def group_values(rows, column, group_by):
    """Group the numeric values of ``column`` by the ``group_by`` field.

    Returns a dict mapping each group name to its list of float values,
    ordered by group name. Raises KeyError if the grouping column is
    missing from the CSV header.
    """
    if rows and group_by not in rows[0]:
        raise KeyError(f"no column {group_by!r}; have {list(rows[0])}")
    groups = {}
    for row in rows:
        groups.setdefault(row[group_by], []).append(float(row[column]))
    return {name: groups[name] for name in sorted(groups)}


def summarize_by(rows, column, group_by):
    """Summarize ``column`` per ``group_by`` group, ordered by group name."""
    return {
        name: summarize(values)
        for name, values in group_values(rows, column, group_by).items()
    }

import argparse

from .core import read_column, summarize, summarize_by


def _format(summary, group=None):
    prefix = f"{group}: " if group is not None else ""
    return (
        f"{prefix}count={summary['count']} mean={summary['mean']:.2f} "
        f"min={summary['min']:.2f} max={summary['max']:.2f}"
    )


def main(argv=None):
    ap = argparse.ArgumentParser(prog="csvstat")
    ap.add_argument("path")
    ap.add_argument("--column", required=True)
    ap.add_argument(
        "--group-by",
        metavar="COLUMN",
        help="print one summary line per group, sorted by group name",
    )
    args = ap.parse_args(argv)
    rows, values = read_column(args.path, args.column)
    if args.group_by is None:
        print(_format(summarize(values)))
    else:
        for group, summary in summarize_by(rows, args.column, args.group_by).items():
            print(_format(summary, group))


if __name__ == "__main__":
    main()
